function studioCloseMenus(restoreFocus=false){studioMenus.forEach(menu=>{menu.classList.remove('open');$$('.studio-submenu',menu).forEach(sub=>sub.classList.remove('open'));$$('[aria-expanded]',menu).forEach(b=>b.setAttribute('aria-expanded','false'));});$$('.menu-item').forEach(b=>{b.setAttribute('aria-expanded','false');b.classList.remove('active');});if(restoreFocus)studioMenuButton?.focus();}
function studioCommand(label,run,enabled=()=>true,shortcut='',attributes={}){const id='command-'+studioCommands.size;studioCommands.set(id,{run,enabled});const button=document.createElement('button');button.type='button';button.setAttribute('role','menuitem');button.tabIndex=-1;button.dataset.command=id;button.append(document.createTextNode(label));if(shortcut){const key=document.createElement('kbd');key.textContent=shortcut;button.append(key);}for(const [key,value] of Object.entries(attributes))button.setAttribute(key,value);return button;}
