function studioOpenSubmenu(button,sub,focus=false){const parent=button.closest('[role=menu]');parent.querySelectorAll(':scope > .studio-submenu').forEach(other=>{if(other!==sub)other.classList.remove('open');});parent.querySelectorAll(':scope > [aria-haspopup]').forEach(other=>other.setAttribute('aria-expanded',String(other===button)));studioRefresh(sub);sub.classList.add('open');const rect=button.getBoundingClientRect(),w=sub.offsetWidth,h=sub.offsetHeight;sub.style.left=Math.max(6,Math.min(rect.right+w+8>innerWidth?rect.left-w:rect.right,innerWidth-w-6))+'px';sub.style.top=Math.max(6,Math.min(rect.top,innerHeight-h-6))+'px';if(focus)sub.querySelector('button:not(:disabled)')?.focus();}
