for(const menu of studioMenus){menu.classList.add('clip-context-menu','studio-menu');menu.setAttribute('role','menu');menu.querySelectorAll('button').forEach(b=>{b.type='button';b.tabIndex=-1;b.setAttribute('role','menuitem');});menu.addEventListener('click',event=>{const button=event.target.closest('[data-command]');if(!button)return;event.stopImmediatePropagation();if(button.disabled)return;const command=studioCommands.get(button.dataset.command);studioCloseMenus();if(command.enabled())Promise.resolve().then(command.run).catch(error=>toast(error.message));},true);menu.querySelectorAll(':scope > button:not([aria-haspopup])').forEach(button=>button.addEventListener('pointerenter',()=>{menu.querySelectorAll(':scope > .studio-submenu').forEach(sub=>sub.classList.remove('open'));menu.querySelectorAll(':scope > [aria-expanded]').forEach(b=>b.setAttribute('aria-expanded','false'));}));}
// Preserve the existing Edit actions and their dynamic enabled state.
function studioOpenMenu(button,menu){const wasOpen=menu.classList.contains('open');studioCloseMenus();if(wasOpen)return;studioMenuButton=button;studioRefresh(menu);if(menu===editMenu){$('[data-edit=undo]',menu).disabled=!undoHistory.length;$('[data-edit=redo]',menu).disabled=!redoHistory.length;$('[data-edit=copy]',menu).disabled=!selectedTimelineClips.length;$('[data-edit=paste]',menu).disabled=!clipClipboard;}menu.classList.add('open');const rect=button.getBoundingClientRect();menu.style.left=Math.min(rect.left,innerWidth-menu.offsetWidth-8)+'px';menu.style.top=rect.bottom+4+'px';button.setAttribute('aria-expanded','true');}
const topMenus={Archivo:fileMenu,Editar:editMenu,Insertar:insertMenu,Herramientas:toolsMenu};
editMenu.addEventListener('click',event=>{if(event.target.closest('[data-edit]'))studioCloseMenus();});
for(const button of $$('.menu-item')){const menu=topMenus[button.textContent.trim()];if(!menu){button.addEventListener('click',()=>studioCloseMenus(),true);continue;}button.setAttribute('aria-haspopup','menu');button.setAttribute('aria-controls',menu.id);button.setAttribute('aria-expanded','false');button.addEventListener('click',event=>{event.stopImmediatePropagation();studioOpenMenu(button,menu);},true);button.addEventListener('keydown',event=>{if(['ArrowDown','Enter',' '].includes(event.key)){event.preventDefault();event.stopImmediatePropagation();if(!menu.classList.contains('open'))studioOpenMenu(button,menu);menu.querySelector('button:not(:disabled)')?.focus();}});}
document.addEventListener('click',event=>{if(!event.target.closest('.studio-menu,.menu-item'))studioCloseMenus();});
window.addEventListener('resize',()=>studioCloseMenus());
document.addEventListener('keydown',event=>{
  const root=studioMenus.find(menu=>menu.classList.contains('open'));if(!root)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();const sub=document.activeElement?.closest('.studio-submenu');if(sub){sub.classList.remove('open');const parent=$('[aria-controls="'+sub.id+'"]',root);parent.setAttribute('aria-expanded','false');parent.focus();}else studioCloseMenus(true);return;}
  const target=event.target.closest('.studio-menu');if(!target)return;
  if(event.key==='Tab'){studioCloseMenus();return;}if(['ArrowUp','ArrowDown','Home','End'].includes(event.key)){event.preventDefault();event.stopImmediatePropagation();const buttons=[...target.children].filter(el=>el.tagName==='BUTTON'&&!el.disabled),index=buttons.indexOf(document.activeElement);buttons[event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}
  if(event.key==='ArrowRight'&&event.target.hasAttribute('aria-controls')){event.preventDefault();studioOpenSubmenu(event.target,document.getElementById(event.target.getAttribute('aria-controls')),true);}
  if(event.key==='ArrowLeft'&&target.classList.contains('studio-submenu')){event.preventDefault();target.classList.remove('open');const parent=$('[aria-controls="'+target.id+'"]',root);parent.setAttribute('aria-expanded','false');parent.focus();}
  event.stopImmediatePropagation();
},true);
